import docx
from docx.shared import Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.style import WD_STYLE_TYPE
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

d = docx.Document('ref_base.docx')
def setf(s, size=None, bold=None, italic=None, caps=None, before=None, after=None, align=None, color=None, line=None, keep=None):
    f = s.font
    f.name = 'Times New Roman'
    rpr = s.element.get_or_add_rPr()
    rf = rpr.find(qn('w:rFonts'))
    if rf is None:
        rf = OxmlElement('w:rFonts'); rpr.insert(0, rf)
    for a in ('w:ascii','w:hAnsi','w:cs','w:eastAsia'):
        rf.set(qn(a), 'Times New Roman')
    if size: f.size = Pt(size)
    if bold is not None: f.bold = bold
    if italic is not None: f.italic = italic
    if color is not None: f.color.rgb = RGBColor(*color)
    else: f.color.rgb = RGBColor(0,0,0)
    if caps: f.all_caps = True
    pf = s.paragraph_format
    if before is not None: pf.space_before = Pt(before)
    if after is not None: pf.space_after = Pt(after)
    if align is not None: pf.alignment = align
    if line is not None: pf.line_spacing = line
    if keep is not None: pf.keep_with_next = keep

S = d.styles
names = [s.name for s in S]
def g(n):
    try: return S[n]
    except KeyError: return None

for n in ['Normal','Body Text','First Paragraph','Compact']:
    s=g(n)
    if s: setf(s, size=11, after=8, line=1.15, align=WD_ALIGN_PARAGRAPH.JUSTIFY)
s=g('Normal')
if s: setf(s, size=11, after=8, line=1.15)
for n in ['Body Text','First Paragraph','Compact']:
    s=g(n)
    if s: setf(s, size=11, after=8, line=1.15, align=WD_ALIGN_PARAGRAPH.JUSTIFY)
if g('Block Text'):
    setf(g('Block Text'), size=10.5, after=8, line=1.0)
if g('Title'): setf(g('Title'), size=16, bold=True, before=0, after=6, align=WD_ALIGN_PARAGRAPH.CENTER, keep=True)
if g('Subtitle'): setf(g('Subtitle'), size=12, bold=False, italic=True, after=6, align=WD_ALIGN_PARAGRAPH.CENTER)
put = {
 'Heading 1': dict(size=12, bold=True, before=20, after=10, align=WD_ALIGN_PARAGRAPH.CENTER, keep=True),
 'Heading 2': dict(size=11.5, bold=True, before=14, after=6, align=WD_ALIGN_PARAGRAPH.LEFT, keep=True),
 'Heading 3': dict(size=11, bold=True, italic=True, before=10, after=4, align=WD_ALIGN_PARAGRAPH.LEFT, keep=True),
 'Heading 4': dict(size=11, bold=True, italic=True, before=8, after=4, align=WD_ALIGN_PARAGRAPH.LEFT, keep=True),
 'TOC Heading': dict(size=12, bold=True, before=0, after=12, align=WD_ALIGN_PARAGRAPH.CENTER),
}
for n, kw in put.items():
    s=g(n)
    if s: setf(s, **kw); s.font.all_caps=False
if g('Caption'): setf(g('Caption'), size=9.5, italic=True, after=6, align=WD_ALIGN_PARAGRAPH.LEFT)
d.save('ref.docx')
print('ref ok', [x for x in names if 'Head' in x or x in ('Normal','Title')])
EOF"}

